sys_script_include.script:
var SharkLearningUtils = Class.create();
SharkLearningUtils.prototype = {
    initialize: function() {
    },

	refQualTraining: function(){
		var trainingsNotToBeShown = [];

		//Verifica os treinamentos em que estou matriculado
		var grEnrollment = new GlideRecord("x_1593181_shark_0_enrollment");
		grEnrollment.addEncodedQuery("studentDYNAMIC90d1921e5f510100a9ad2572f2b477fe^stateIN2,3");
		grEnrollment.query();
		while(grEnrollment.next()){
			trainingsNotToBeShown.push(grEnrollment.training.sys_id.toString());
		}

		var trainingsToBeShown = [];

		//Define quais treinamentos devem ser mostrados
		var grTraining = new GlideRecord("x_1593181_shark_0_training");
		grTraining.addQuery("available_seats", "!=", 0);	// Apenas treinamentos com vagas abertas
		grTraining.query();
		while(grTraining.next()){
			var trainingSys_ID = grTraining.sys_id.toString();

			//Verifica se já possui 3 matrículas
			var gagEnrollment = new GlideAggregate("x_1593181_shark_0_enrollment");
			gagEnrollment.addEncodedQuery("studentDYNAMIC90d1921e5f510100a9ad2572f2b477fe^stateIN2,3");
			gagEnrollment.addEncodedQuery("training.course=" + grTraining.course.sys_id.toString());
			gagEnrollment.addQuery("state", "!=", 4);
			gagEnrollment.addAggregate("COUNT");
			gagEnrollment.query();

			var maxEnrolls = false;

			if(gagEnrollment.next() && gagEnrollment.getAggregate("COUNT") >= 3){
				maxEnrolls = true;
			}

			var userID = gs.getUserID(); // Captura usuário atualmente logado

			// Verifica a data dos Treinamentos
			var reachedLimitDate = false;
			var today = new GlideDate();

			var glideTrainingDate = new GlideDate();
			glideTrainingDate.setValue(grTraining.date);

			if(today.compareTo(glideTrainingDate) > 0){
				reachedLimitDate = true;
			}

			//Verifica se eu sou o instrutor, se atingiu o número máximo de inscrições e a data do treinamento.
			if(trainingsNotToBeShown.indexOf(trainingSys_ID) == -1 && maxEnrolls == false && grTraining.instructor.user != userID && reachedLimitDate == false){
				trainingsToBeShown.push(trainingSys_ID);
			}
		}

		if(trainingsToBeShown.length === 0){
			return "sys_idIN123445";
		} else {
			return "sys_idIN" + trainingsToBeShown.join(",");
		}

	},

    type: 'SharkLearningUtils'
};
